<h1><?= te('Hotel and vendor payments') ?></h1><form class="card row" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="invoice"><div><label><?= te('Hotel / vendor') ?></label><input name="vendor_name" required></div><div><label><?= te('Invoice reference') ?></label><input name="reference" required></div><div><label><?= te('Amount') ?></label><input name="amount" type="number" min="0.01" step="0.01" required></div><div><label><?= te('Due date') ?></label><input name="due_on" type="date" required></div><div><label><?= te('Purchase order (optional)') ?></label><select name="purchase_order_id"><option value=""><?= te('None') ?></option><?php foreach($orders as $o): ?><option value="<?= (int)$o['id'] ?>"><?= e($o['reference'].' · '.$o['vendor_name'].' · '.money($o['total'])) ?></option><?php endforeach; ?></select></div><button class="btn"><?= te('Record invoice') ?></button></form><?php foreach($invoices as $i): ?><div class="card"><h2><?= e($i['vendor_name'].' · '.$i['reference']) ?><?= $i['po_reference'] ? ' · '.e($i['po_reference']) : '' ?></h2><p><?= money($i['amount']) ?> · <?= e($i['status'].' · due '.$i['due_on'].' · '.$i['payment_method'].' · '.$i['payment_reference']) ?></p><form class="row" method="post"><?= csrf_field() ?><input type="hidden" name="invoice_id" value="<?= (int)$i['id'] ?>"><?php if($i['status']==='received'): ?><input type="hidden" name="do" value="approve"><button class="btn"><?= te('Approve') ?></button><?php elseif($i['status']==='approved'): ?><input type="hidden" name="do" value="pay"><select name="payment_method"><option value="transfer"><?= te('transfer') ?></option><option value="check"><?= te('check') ?></option><option value="cash"><?= te('cash') ?></option><option value="card"><?= te('card') ?></option></select><input name="payment_reference" required placeholder="<?= te('Payment reference') ?>"><button class="btn"><?= te('Record payment') ?></button><?php endif; ?></form></div><?php endforeach; ?>